package com.nook.security;
import com.nook.application.port.out.UserAccountStatusPort; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.*;
@Component public class JwtFilter extends OncePerRequestFilter { private final JwtService jwt;private final UserAccountStatusPort users; public JwtFilter(JwtService jwt,UserAccountStatusPort users){this.jwt=jwt;this.users=users;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{UUID id=jwt.parse(h.substring(7));if(users.isActive(id))SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(id,null,List.of()));}catch(Exception ignored){}chain.doFilter(req,res);} }
